  'Official contact addresses, billing contacts, and external support channels should be configured by the PlayHub site administrator for this deployment. This page intentionally does not display unverified email addresses.' => 'ოფიციალური საკონტაქტო მისამართები, ბილინგის კონტაქტები და გარე მხარდაჭერის არხები უნდა იყოს კონფიგურირებული PlayHub საიტის ადმინისტრატორის მიერ ამ განლაგებისთვის. ეს გვერდი განზრახ არ აჩვენებს დაუდასტურებელ ელფოსტის მისამართებს.',
