  'Playback' => 'დაკვრა',
  'Playback progress, watch-later state, likes, comments, subscriptions, notifications, and admin analytics are saved when linked to authenticated platform features.' => 'დაკვრის პროგრესი, მოგვიანებით ყურების მდგომარეობა, მოწონებები, კომენტარები, გამოწერები, შეტყობინებები და ადმინისტრატორის ანალიტიკა ინახება მონაცემთა ბაზაში, როდესაც დაკავშირებულია ავთენტიფიცირებულ პლატფორმის ფუნქციებთან.',
  'Playback, comments, likes, watch later, subscriptions, notifications, messages, playlists, and language settings are available through the main navigation and account menu.' => 'დაკვრა, კომენტარები, მოწონებები, მოგვიანებით ყურება, გამოწერები, შეტყობინებები, შეტყობინებები, დასაკრავი სიები და ენის პარამეტრები ხელმისაწვდომია მთავარი ნავიგაციისა და ანგარიშის მენიუდან.',
  'PlayHub' => 'PlayHub',
  'PlayHub is a video platform for uploading, watching, scheduling, managing, and moderating creator content from one account.' => 'PlayHub არის ვიდეო პლატფორმა ერთი ანგარიშიდან შემქმნელის შინაარსის ატვირთვის, ყურების, დაგეგმვის, მართვისა და მოდერაციისთვის.',
  'PlayHub is the video platform running on this deployment, built for creators, viewers, communities, and platform operators.' => 'PlayHub არის ვიდეო პლატფორმა, რომელიც მუშაობს ამ განლაგებაზე, შექმნილია შემქმნელებისთვის, მნახველებისთვის, თემებისთვის და პლატფორმის ოპერატორებისთვის.',
  'PlayHub provides creator channels, video uploads, scheduled publishing, subscriptions, comments, playlists, watch later, live content pages, and administration tools from one platform.' => 'PlayHub გთავაზობთ შემქმნელთა არხებს, ვიდეოების ატვირთვას, დაგეგმილ გამოქვეყნებას, გამოწერებს, კომენტარებს, დასაკრავი სიებს, მოგვიანებით ყურებას, პირდაპირი კონტენტის გვერდებს და ადმინისტრირების ხელსაწყოებს ერთი პლატფორმიდან.',
  'PlayHub uses essential cookies and browser storage for login sessions, API authentication, CSRF/security behavior, language selection, theme selection, account menu state, and other features required for the application to work.' => 'PlayHub იყენებს აუცილებელ ქუქი-ფაილებს და ბრაუზერის მეხსიერებას შესვლის სესიებისთვის, API ავთენტიფიკაციისთვის, CSRF/უსაფრთხოების ქცევისთვის, ენის არჩევისთვის, თემის არჩევისთვის, ანგარიშის მენიუს მდგომარეობასა და აპლიკაციის მუშაობისთვის საჭირო სხვა ფუნქციებს.',
