  'Sign in and use Settings for account, profile, password, notification, privacy, and creator preferences. Creator upload and content issues should include the video title, channel, browser, and any processing error shown on the upload page.' => 'შედით და გამოიყენეთ პარამეტრები ანგარიშის, პროფილის, პაროლის, შეტყობინების, კონფიდენციალურობისა და შემქმნელის პრეფერენციებისთვის. შემქმნელის ატვირთვისა და კონტენტის პრობლემები უნდა მოიცავდეს ვიდეოს სათაურს, არხს, ბრაუზერს და ატვირთვის გვერდზე ნაჩვენები დამუშავების ნებისმიერ შეცდომას.',
