  'The configured' => 'კონფიგურირებული',
  'The developer page is connected to the Laravel backend: route inventory, platform counts, upload limits, and metadata are loaded from /api/developers.' => 'დეველოპერის გვერდი დაკავშირებულია ცოცხალ Laravel-თან: მარშრუტების ინვენტარი, მონაცემთა ბაზის რაოდენობა, ატვირთვის ლიმიტები და პლატფორმის მეტამონაცემები იტვირთება /api/დეველოპერებიდან.',
  'The frontend stores preferences such as selected language, theme, playback queue, watch progress, and interface state so the experience remains consistent across page navigation and reloads.' => 'ფრონტენტი ინახავს პრეფერენციებს, როგორიცაა არჩეული ენა, თემა, დაკვრის რიგი, ყურების პროგრესი და ინტერფეისის მდგომარეობა, ასე რომ გამოცდილება რჩება თანმიმდევრული გვერდის ნავიგაციასა და გადატვირთვაში.',
  'The processing job encodes renditions, creates thumbnails when needed, stores captions, and marks videos ready when processing completes. Future scheduled videos remain private until the scheduler releases them.' => 'დამუშავების სამუშაო დაშიფვრავს რენდირებას, საჭიროების შემთხვევაში ქმნის ესკიზებს, ინახავს სუბტიტრებს და მონიშნავს ვიდეოებს მზადყოფნისას დამუშავების დასრულებისას. მომავალი დაგეგმილი ვიდეოები კონფიდენციალური რჩება, სანამ დამგეგმავი არ გამოაქვეყნებს მათ.',
  'The upload system supports categories and languages from the API, processes uploaded videos, stores thumbnails and captions, and keeps scheduled content private until its release time.' => 'ატვირთვის სისტემა მხარს უჭერს მონაცემთა ბაზას, მხარს უჭერს კატეგორიებსა და ენებს API-დან, ამუშავებს ატვირთულ ვიდეოებს, ინახავს ესკიზებსა და სუბტიტრებს და ინახავს დაგეგმილ შინაარსს კონფიდენციალურად გამოშვებამდე.',
  'This page explains how PlayHub uses cookies and browser storage for sessions, security, preferences, playback, and authenticated features.' => 'ეს გვერდი განმარტავს, თუ როგორ იყენებს PlayHub ქუქი-ფაილებს და ბრაუზერის საცავს სესიებისთვის, უსაფრთხოებისთვის, პრეფერენციებისთვის, დაკვრისთვის და ავთენტიფიცირებული ფუნქციებისთვის.',
