  'Uploaded videos' => 'ატვირთული ვიდეოები',
  'Uploaded videos are encoded into playable renditions. Processing time depends on file size, duration, server load, and queue status. The upload page and Creator Studio show the current processing status.' => 'ატვირთული ვიდეოები დაშიფრულია დაკვრად შესასრულებლად. დამუშავების დრო დამოკიდებულია ფაილის ზომაზე, ხანგრძლივობაზე, სერვერის დატვირთვაზე და რიგის სტატუსზე. ატვირთვის გვერდი და Creator Studio აჩვენებს რეალურ დამუშავების სტატუსს ვიდეო ჩანაწერიდან.',
  'Uploads, scheduling, and processing are available.' => 'შესაძლებელია ატვირთვები, დაგეგმვა და დამუშავება.',
  'Use /api/videos, channel endpoints, and authenticated routes for creator workflows.' => 'გამოიყენეთ /api/ვიდეოები, არხის ბოლო წერტილები და ავტორიზებული მარშრუტები შემქმნელთა სამუშაო ნაკადებისთვის.',
  'Use built-in report actions for videos and comments so admins receive the exact content reference. Admin dashboard pages show users, content, reports, monetization, analytics, support, roles, and system settings.' => 'გამოიყენეთ ჩაშენებული ანგარიშის მოქმედებები ვიდეოებისა და კომენტარებისთვის, რათა ადმინისტრატორებმა მიიღონ ზუსტი შინაარსის მითითება. ადმინისტრატორის დაფის გვერდები იყენებენ მონაცემთა ბაზის ცოცხალ მონაცემებს მომხმარებლებისთვის, შინაარსისთვის, ანგარიშებისთვის, მონეტიზაციისთვის, ანალიტიკისთვის, მხარდაჭერისთვის, როლებისთვის და სისტემის პარამეტრებისთვის.',
  'Use Contact Us' => 'გამოიყენეთ დაგვიკავშირდით',
  'Use JSON for normal API requests and FormData for file uploads. Do not bypass validation: categories and languages use configured IDs, visibility is limited to public, unlisted, or private, and captions accept SRT, VTT, or TXT files.' => 'გამოიყენეთ JSON ჩვეულებრივი API მოთხოვნებისთვის და FormData ფაილის ატვირთვისთვის. Do not bypass validation: categories and languages are database IDs, visibility is limited to public, unlisted, or private, and captions accept SRT, VTT, or TXT files.',
  'Use Settings to update your profile, security, password, two-factor delivery, devices, preferences, and notification options. If you cannot access your account, use the login flow and provide the account email to the site administrator.' => 'გამოიყენეთ პარამეტრები თქვენი პროფილის, უსაფრთხოების, პაროლის, ორფაქტორიანი მიწოდების, მოწყობილობების, პრეფერენციებისა და შეტყობინებების ვარიანტების გასაახლებლად. თუ არ გაქვთ წვდომა თქვენს ანგარიშზე, გამოიყენეთ შესვლის ნაკადი და მიაწოდეთ ანგარიშის ელფოსტა საიტის ადმინისტრატორს.',
  'Use the contact form' => 'გამოიყენეთ საკონტაქტო ფორმა',
  'Use the report actions on videos, comments, and community posts so admins receive the exact content reference.' => 'გამოიყენეთ ანგარიშის მოქმედებები ვიდეოებზე, კომენტარებსა და საზოგადოების პოსტებზე, რათა ადმინისტრატორებმა მიიღონ კონტენტის ზუსტი მითითება.',
  'Use the report actions on videos, comments, and community posts when content may violate platform rules. These reports include the content reference so administrators can review the exact item.' => 'გამოიყენეთ ანგარიშის მოქმედებები ვიდეოებზე, კომენტარებსა და საზოგადოების პოსტებზე, როდესაც კონტენტი შეიძლება არღვევდეს პლატფორმის წესებს. ეს ანგარიშები დაკავშირებულია რეალურ კონტენტთან და უკეთესია ვიდრე ზოგადი შეტყობინება, რადგან ადმინისტრატორებს შეუძლიათ გადახედონ ზუსტ ერთეულს.',
  'Use the right PlayHub channel for account help, content reports, technical issues, and administrator requests.' => 'გამოიყენეთ სწორი PlayHub არხი ანგარიშის დახმარებისთვის, კონტენტის ანგარიშებისთვის, ტექნიკური პრობლემებისა და ადმინისტრატორის მოთხოვნებისთვის.',
  'Video categories' => 'ვიდეო კატეგორიები',
  'Video for everyone. Built for creators and viewers.' => 'ვიდეო ყველასთვის. აშენებულია რეალური პლატფორმის მონაცემებით.',
  'Video upload, scheduling, thumbnails, and processing issues.' => 'ვიდეოს ატვირთვის, დაგეგმვის, ესკიზების და დამუშავების პრობლემები.',
  'Videos, thumbnails, captions, processing.' => 'ვიდეოები, ესკიზები, სუბტიტრები, დამუშავება.',
  'Viewers can browse categories, search videos, watch content, subscribe to channels, save videos to watch later, comment, receive notifications, and manage language and accessibility preferences.' => 'Viewers can browse categories, search videos, watch content, subscribe to channels, save videos to watch later, comment, receive notifications, and manage language and accessibility preferences.',
  'Viewing and community help' => 'ნახვა და საზოგადოების დახმარება',
  'Waiting for backend endpoint inventory.' => 'ელოდება უკანა ბოლო წერტილის ინვენტარს.',
  'We’re here to help.' => 'ჩვენ აქ ვართ დასახმარებლად.',
  'What is PlayHub?' => 'რა არის PlayHub?',
  'What PlayHub does' => 'რას აკეთებს PlayHub',
  'Where do contact messages go?' => 'სად მიდის საკონტაქტო შეტყობინებები?',
  'Why is my video still processing?' => 'რატომ არის ჩემი ვიდეო ჯერ კიდევ დამუშავების პროცესში?',
  'Yes. Use the native schedule date and time field on the upload page. The backend stores scheduled_at, processes the video, keeps it private while the date is in the future, and releases it when the Laravel scheduler runs after the scheduled time.' => 'დიახ. გამოიყენეთ მშობლიური განრიგის თარიღი და დროის ველი ატვირთვის გვერდზე. The backend stores scheduled_at, processes the video, keeps it private while the date is in the future, and releases it when the Laravel scheduler runs after the scheduled time.',
  'Yes. Use the native schedule field on Upload. The backend stores scheduled_at and releases the video after processing when the schedule time is reached.' => 'დიახ. გამოიყენეთ მშობლიური განრიგის ველი ატვირთვაზე. Backend ინახავს scheduled_at-ს და აქვეყნებს ვიდეოს დამუშავების შემდეგ, როდესაც განრიგის დრო მიიღწევა.',
  'You are browsing as a guest. Sign in to access account-specific tools.' => 'თქვენ ათვალიერებთ როგორც სტუმარი. შედით ანგარიშის სპეციფიკურ ინსტრუმენტებზე წვდომისთვის.',
  'You are responsible for your account credentials, profile activity, uploaded content, comments, messages, and any creator or admin actions performed from your account. Use strong passwords and keep two-factor delivery methods current.' => 'თქვენ ხართ პასუხისმგებელი თქვენი ანგარიშის სერთიფიკატებზე, პროფილის აქტივობაზე, ატვირთულ კონტენტზე, კომენტარებზე, შეტყობინებებზე და თქვენი ანგარიშიდან შესრულებულ შემქმნელზე ან ადმინისტრატორზე. გამოიყენეთ ძლიერი პაროლები და შეინახეთ მიწოდების ორფაქტორიანი მეთოდები.',
  'You can clear browser cookies and local storage in your browser settings. Clearing essential storage may sign you out, reset language/theme preferences, remove local playback state, and require you to log in again.' => 'თქვენ შეგიძლიათ წაშალოთ ბრაუზერის ქუქი-ფაილები და ადგილობრივი მეხსიერება თქვენი ბრაუზერის პარამეტრებში. არსებითი მეხსიერების გასუფთავებამ შეიძლება გამოხვიდეთ სისტემიდან, გადააყენოს ენის/თემის პარამეტრები, წაშალოს დაკვრის ადგილობრივი მდგომარეობა და მოგთხოვოთ ხელახლა შესვლა.',
  'You receive a response by email.' => 'პასუხს იღებთ ელექტრონული ფოსტით.',
  'You’re in control' => 'თქვენ აკონტროლებთ',
  'Your choices' => 'შენი არჩევანი',
